    it "is not possible for an already started poll" do
      current_question = create(:poll_question, poll: current_poll, title: "Sample title")

      patch :update, params: {
        poll_question: {
          translations_attributes: {
            "0" => {
              locale: "en",
              title: "New title",
              id: current_question.translations.first.id
            }
          }
        },
        id: current_question
      }

